"use client"
import type { KeyboardEvent } from "react"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"

/** Gap: ListRow — CAND-002 in atlas/state/candidates.json. No list-row component exists yet. */
export function ListRow({
  title,
  subtitle,
  trailing,
  onClick,
}: {
  title: string
  subtitle: string
  trailing: React.ReactNode
  onClick: () => void
}) {
  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault()
      onClick()
    }
  }
  return (
    <div
      role="button"
      tabIndex={0}
      onClick={onClick}
      onKeyDown={onKeyDown}
      style={{
        display: "flex",
        alignItems: "center",
        gap: "var(--atlas-spacing-3)",
        paddingBlock: "var(--atlas-spacing-3)",
        paddingInline: "var(--atlas-spacing-4)",
        borderRadius: "var(--atlas-radius-md)",
        cursor: "pointer",
      }}
    >
      <div
        aria-hidden
        style={{
          width: "var(--atlas-spacing-10)",
          height: "var(--atlas-spacing-10)",
          borderRadius: "var(--atlas-radius-full)",
          backgroundColor: "var(--atlas-primary-subtle)",
          color: "var(--atlas-primary)",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          fontWeight: "var(--atlas-font-weight-semibold)",
          fontSize: "var(--atlas-font-size-sm)",
          flexShrink: 0,
        }}
      >
        {title
          .split(" ")
          .map((part) => part[0])
          .slice(0, 2)
          .join("")
          .toUpperCase()}
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-0_5)", flex: 1, minWidth: 0 }}>
        <span style={{ fontSize: "var(--atlas-text-body)", fontWeight: "var(--atlas-font-weight-medium)", color: "var(--atlas-foreground)" }}>
          {title}
        </span>
        <span style={{ fontSize: "var(--atlas-text-caption)", color: "var(--atlas-foreground-muted)" }}>{subtitle}</span>
      </div>
      {trailing}
    </div>
  )
}

export function SummaryRow({ label, value, emphasis }: { label: string; value: string; emphasis?: boolean }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
      <span style={{ fontSize: "var(--atlas-text-body-sm)", color: "var(--atlas-foreground-muted)" }}>{label}</span>
      <span
        style={{
          fontSize: emphasis ? "var(--atlas-text-h4)" : "var(--atlas-text-body-sm)",
          fontWeight: emphasis ? "var(--atlas-font-weight-semibold)" : "var(--atlas-font-weight-regular)",
          color: "var(--atlas-foreground)",
        }}
      >
        {value}
      </span>
    </div>
  )
}

export function CurrencyBadge({ currency }: { currency: string }) {
  return (
    <Badge variant="secondary" size="sm">
      {currency}
    </Badge>
  )
}

