"use client"
import { useMemo, useState } from "react"
import { Label } from "@atlas/ui-web/primitives/Label/Label"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { RECENT_RECIPIENTS } from "../schema"
import type { SendMoneyStepProps } from "../schema"
import { ListRow, CurrencyBadge } from "./_parts"

const SearchIcon = () => (
  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden>
    <circle cx="11" cy="11" r="7" />
    <line x1="21" y1="21" x2="16.65" y2="16.65" />
  </svg>
)

export function Recipient({ patch, next }: SendMoneyStepProps) {
  const [query, setQuery] = useState("")

  const filtered = useMemo(
    () => RECENT_RECIPIENTS.filter((r) => r.name.toLowerCase().includes(query.trim().toLowerCase())),
    [query],
  )

  const select = (id: string) => {
    const recipient = RECENT_RECIPIENTS.find((r) => r.id === id)
    if (!recipient) return
    patch({
      recipientId: recipient.id,
      recipientName: recipient.name,
      maskedAccount: recipient.maskedAccount,
      currency: recipient.currency,
    })
    next()
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-4)", paddingInline: "var(--atlas-spacing-4)" }}>
      <Label htmlFor="recipient-search" size="sm">
        Search recipients
      </Label>
      <Input
        id="recipient-search"
        variant="default"
        size="md"
        leadingIcon={<SearchIcon />}
        placeholder="Search by name"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
      />

      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1)" }}>
        <span
          style={{
            fontSize: "var(--atlas-text-caption)",
            color: "var(--atlas-foreground-muted)",
            fontWeight: "var(--atlas-font-weight-medium)",
            paddingInline: "var(--atlas-spacing-4)",
          }}
        >
          Recent recipients
        </span>
        <div style={{ display: "flex", flexDirection: "column" }}>
          {filtered.map((r) => (
            <ListRow
              key={r.id}
              title={r.name}
              subtitle={r.maskedAccount}
              trailing={<CurrencyBadge currency={r.currency} />}
              onClick={() => select(r.id)}
            />
          ))}
          {filtered.length === 0 && (
            <span
              style={{
                fontSize: "var(--atlas-text-body-sm)",
                color: "var(--atlas-foreground-muted)",
                paddingInline: "var(--atlas-spacing-4)",
                paddingBlock: "var(--atlas-spacing-3)",
              }}
            >
              No recipients match “{query}”.
            </span>
          )}
        </div>
      </div>
    </div>
  )
}

